import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.ContainerRegistryCleanup{RemovedContainers: []protocol.FullContainerName{{ContainerID: 7,
# DynamicContainerID: protocol.Option[uint32](9)}, {ContainerID: 2}}}
GOLDEN = bytes.fromhex("020701090000000200")

GOLDENS = [
    pytest.param(
        v2225.ContainerRegistryCleanupPacket(
            removed_containers=[
                v2225.FullContainerName(name=v2225.ContainerEnumName.LEVEL_ENTITY_CONTAINER, dynamic_id=9),
                v2225.FullContainerName(name=v2225.ContainerEnumName.ANVIL_RESULT_PREVIEW_CONTAINER, dynamic_id=None),
            ]
        ),
        GOLDEN,
        id="two-containers",
    )
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_registry_cleanup_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_registry_cleanup_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
